function patchStrings(target,de,localized){
  if(!target||de==null||localized==null)return;
  if(Array.isArray(de)&&Array.isArray(localized)&&Array.isArray(target)){
    const n=Math.min(de.length,localized.length,target.length);
    for(let i=0;i<n;i++){
      if(typeof de[i]==='string'&&typeof localized[i]==='string')target[i]=localized[i];
      else if(de[i]&&localized[i]&&target[i])patchStrings(target[i],de[i],localized[i]);
    }
    return;
  }
  if(typeof de==='object'&&typeof localized==='object'&&typeof target==='object'){
    for(const k of Object.keys(de)){
      if(!(k in localized)||!(k in target))continue;
      if(typeof de[k]==='string'&&typeof localized[k]==='string')target[k]=localized[k];
      else if(de[k]&&localized[k]&&target[k])patchStrings(target[k],de[k],localized[k]);
    }
  }
}
